// Keep only connected accounts on the platforms chosen in the configuration.
const cfg = $('Set Brand and Style').first().json;
const wanted = String(cfg.platformFilter || '').split(',').map(s => s.trim().toUpperCase()).filter(Boolean);
const accounts = $input.all().map(i => i.json);

const selected = accounts.filter(a => {
  const status = String(a.connectionStatus || 'CONNECTED').toUpperCase();
  const platform = String(a.platform || '').toUpperCase();
  return status === 'CONNECTED' && (wanted.length === 0 || wanted.includes(platform));
});

if (selected.length === 0) {
  throw new Error('No connected accounts matched the platform filter. Check the Set Brand and Style node and your PostFast connections.');
}
if (selected.length > 8) {
  throw new Error('More than 8 matching accounts. The upload endpoint issues at most 8 image URLs per request, so narrow the platform filter.');
}

return [{ json: {
  accountIds: selected.map(a => a.id ?? a.socialMediaId)
} }];

// One upload per account: pair each pre-signed URL with an account and attach the image binary.
const raw = $('Get Upload URL').all().map(i => i.json);
let urls = raw;
if (raw.length === 1 && Array.isArray(raw[0])) urls = raw[0];
else if (raw.length === 1 && Array.isArray(raw[0].data)) urls = raw[0].data;
else if (raw.length === 1 && Array.isArray(raw[0].urls)) urls = raw[0].urls;

const accountIds = $('Filter Target Accounts').first().json.accountIds;
if (urls.length < accountIds.length) {
  throw new Error(`Got ${urls.length} signed URLs for ${accountIds.length} accounts. Check the Get Upload URL node's count.`);
}

const binary = $('Generate Post Image').first().binary;
return accountIds.map((accountId, i) => ({
  json: { accountId, signedUrl: urls[i].signedUrl, key: urls[i].key },
  binary
}));

// One scheduled post per account, each with its own uploaded media key.
const uploads = $('Prepare Uploads').all().map(i => i.json);
const caption = $('Write Caption and Image Prompt').first().json.message.content.caption;
const when = new Date(Date.now() + 60 * 60 * 1000).toISOString();

return uploads.map(u => ({ json: {
  socialMediaId: u.accountId,
  content: caption,
  scheduledAt: when,
  mediaItemsJson: JSON.stringify([{ key: u.key, type: 'IMAGE', sortOrder: 0 }])
} }));
